#include <vector>
#include <stack>

using namespace std;

class Solution {
public:
    vector<int> finalPrices(vector<int>& prices) {
        stack<int> st;
        vector<int> res(prices);

        for (int i = prices.size() - 1; i >= 0; --i) {
            while (!st.empty() && st.top() > prices[i])
                st.pop();
            if (!st.empty())
                res[i] -= st.top();
            st.push(prices[i]);
        }
        return res;
    }
};
